    function buildExtractBody() {
      const body = {
        url: documentUrl.value.trim(),
        mode: mode.value,
        includeRawText: includeRawText.checked,
        includeChunks: includeChunks.checked,
        useBrowserFallback: useBrowserFallback.checked,
        useOcrFallback: useOcrFallback.checked
      };

      const parsedMaxTextChars = Number(maxTextChars.value);
      if (Number.isInteger(parsedMaxTextChars) && parsedMaxTextChars >= 1000) {
        body.maxTextChars = parsedMaxTextChars;
      }

      return body;
    }

    function refreshJsonBody() {
      requestBody.value = JSON.stringify(buildExtractBody(), null, 2);
    }

    function endpointUrl() {
      const root = baseUrl.value.trim().replace(/\/+$/, "");
      const path = targetPath.value.trim().replace(/^\/?/, "/");
      return `${root}${path}`;
    }

    function shellQuote(value) {
      return `'${String(value).replaceAll("'", "'\\''")}'`;
    }

    function buildCurlCommand() {
      const parts = ["curl", "-sS", shellQuote(endpointUrl())];
      const key = apiKey.value.trim();

      if (key.length > 0) {
        parts.push("-H", shellQuote(`Authorization: Bearer ${key}`));
      }

      if (method.value !== "GET") {
        parts.push("-H", shellQuote("content-type: application/json"));
        parts.push("-d", shellQuote(requestBody.value.trim()));
      }

      if (method.value !== "GET") {
        parts.splice(1, 0, "-X", method.value);
      }

      return parts.join(" \\\n  ");
    }

    function refreshCurlCommand() {
      curlOutput.textContent = buildCurlCommand();
    }

    function setStatus(message) {
      statusEl.textContent = message;
    }

    function show(value) {
      if (typeof value === "string") {
        output.textContent = value;
        return;
      }

      output.textContent = JSON.stringify(value, null, 2);
    }

    async function copyText(value, label) {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(value);
      } else {
        const scratch = document.createElement("textarea");
        scratch.value = value;
        scratch.style.position = "fixed";
        scratch.style.left = "-9999px";
        document.body.appendChild(scratch);
        scratch.select();
        document.execCommand("copy");
        scratch.remove();
      }

      setStatus(`${label} copied.`);
    }

    syncBody.addEventListener("click", () => {
      refreshJsonBody();
      refreshCurlCommand();
    });

    copyCurl.addEventListener("click", async () => {
