        const startedAt = performance.now();
        const response = await fetch(url, {
          method: selectedMethod,
          headers,
          body
        });
        const elapsedMs = Math.round(performance.now() - startedAt);
        const text = await response.text();
        const contentType = response.headers.get("content-type") || "";

        setStatus(`${response.status} ${response.statusText} in ${elapsedMs}ms`);

        if (contentType.includes("application/json")) {
          show(JSON.parse(text));
        } else {
          show(text);
        }
      } catch (error) {
        setStatus("Request failed. If this page is opened from file://, the browser may require CORS on the API.");
        show(String(error));
      }
    });

    for (const element of [baseUrl, targetPath, method, apiKey, requestBody]) {
      element.addEventListener("change", refreshCurlCommand);
      element.addEventListener("input", refreshCurlCommand);
